@Composable
fun SessionScreen(
    username: String,
    onNavigateToLeaderboard: () -> Unit,
    onNavigateBack: () -> Unit,
) {
    val viewModel = koinViewModel<SessionViewModel>()
    DisposableEffect(username) {
        viewModel.init(username)
        onDispose {}
    }
    val viewState by viewModel.viewState.collectAsState()

    SessionScreenContent(
        username = username,
        viewState = viewState,
        onEvent = viewModel::handleEvent,
        onNavigateToLeaderboard = onNavigateToLeaderboard,
        onNavigateBack = onNavigateBack,
    )
}

@Composable
private fun SessionScreenContent(
    username: String,
    viewState: SessionViewState,
    onEvent: (SessionViewEvent) -> Unit,
    onNavigateToLeaderboard: () -> Unit,
    onNavigateBack: () -> Unit,
) {
    var bookTitle by remember { mutableStateOf("") }

    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(text = "Hello, $username")

        when (viewState) {
            is SessionViewState.Active -> {
                val hours = viewState.elapsedSec / 3600
                val minutes = (viewState.elapsedSec % 3600) / 60
                val seconds = viewState.elapsedSec % 60
                Text(text = "Reading: ${viewState.bookTitle}")
                Text(text = "${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}")
                Button(
                    onClick = { onEvent(SessionViewEvent.StopReading) },
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                ) {
                    Text("Stop Reading")
                }
            }
            else -> {
                OutlinedTextField(
                    value = bookTitle,
                    onValueChange = { bookTitle = it },
                    label = { Text("Book title") },
                    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                )
                Button(
                    onClick = { onEvent(SessionViewEvent.StartReading(bookTitle)) },
                    enabled = bookTitle.isNotBlank() && viewState !is SessionViewState.Loading,
                    modifier = Modifier.fillMaxWidth(),
                ) {
                    Text("Start Reading")
                }
            }
        }

        Button(
            onClick = onNavigateToLeaderboard,
            modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
        ) {
            Text("View Leaderboard")
        }
        Button(
            onClick = onNavigateBack,
            modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
        ) {
            Text("Back")
        }
    }
}

