package com.bookreads.di

import com.bookreads.storage.LocalStorageService
import com.bookreads.storage.PrefPathProvider
import com.bookreads.storage.PrefPathProviderIos
import com.bookreads.storage.PrefServiceDataStore
import org.koin.core.module.Module
import org.koin.dsl.module

actual val coreStorageModule: Module = module {
    single<PrefPathProvider> { PrefPathProviderIos() }
    single<LocalStorageService> { PrefServiceDataStore(get()) }
}

package com.bookreads.storage

import okio.Path
import okio.Path.Companion.toPath
import platform.Foundation.NSDocumentDirectory
import platform.Foundation.NSSearchPathForDirectoriesInDomains
import platform.Foundation.NSUserDomainMask

class PrefPathProviderIos : PrefPathProvider {
    override fun get(): Path {
        val dir = NSSearchPathForDirectoriesInDomains(
            NSDocumentDirectory,
            NSUserDomainMask,
            true,
        ).first() as String
        return "$dir/bookreads_prefs.json".toPath()
    }
}

