import org.koin.compose.viewmodel.koinViewModel

@Composable
fun HomeScreen(
    onNavigateToSession: (String) -> Unit,
    onNavigateToLeaderboard: () -> Unit,
) {
    val viewModel = koinViewModel<HomeViewModel>()
    viewModel.onNavigateToSession = onNavigateToSession
    val viewState by viewModel.viewState.collectAsState()

    HomeScreenContent(
        viewState = viewState,
        onEvent = viewModel::handleEvent,
        onNavigateToLeaderboard = onNavigateToLeaderboard,
    )
}

@Composable
private fun HomeScreenContent(
    viewState: HomeViewState,
    onEvent: (HomeViewEvent) -> Unit,
    onNavigateToLeaderboard: () -> Unit,
) {
    var username by remember { mutableStateOf("") }

    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(text = "Book Reading Leaderboard")
        OutlinedTextField(
            value = username,
            onValueChange = { username = it },
            label = { Text("Username") },
            modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
        )
        Button(
            onClick = { onEvent(HomeViewEvent.EnterUsername(username)) },
            enabled = username.isNotBlank() && viewState !is HomeViewState.Loading,
            modifier = Modifier.fillMaxWidth(),
        ) {
            Text("Enter")
        }
        Button(
            onClick = onNavigateToLeaderboard,
            modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
        ) {
            Text("View Leaderboard")
        }
        if (viewState is HomeViewState.Error) {
            Text(text = viewState.message)
        }
    }
}

